export const synastryShort = {
  ariesvsaries: `DVA VŮDCOVÉ - Všechno závisí na tom, zda sdílíte stejné cíle a zásady. Z krajně pozitivního hlediska se budete společně řítit životem nekomplikovaným způsobem, dostanete se tam, kam se dostat chcete, jako pár i jako nezávislé lidské bytosti. Avšak pokud jsou vaše cíle příliš rozdílné, budete zřejmě jedním ze sběratelů vzpomínek na krátkodobé vztahy!`,
  ariesvstaurus: `VŮDCE A BANKÉŘ - Vaše kritéria jsou velmi odlišná. Beran chápe život z hlediska postupování kupředu bez ohledu na cokoli; Býk z hlediska zvažování ceny a lpění na tom, co má. Kdybyste byli schopni setkat se v půli cesty, mohl by váš vztah uspokojit zároveň základní potřeby jednoho i touhu druhého jít dopředu. Ale jedno silné a jedno tvrdohlavé ego toho zpravidla nikdy nedosáhnou.`,
  ariesvsgemini: `VŮDCE A ŠPRÝMAŘ - Toto je mladistvé spojení, které s sebou pochopitelně přináší výšky a pády, jež taková rychlost, nadšení a vlastní zájem plodí. Dokud trvá, může být podnětné a nekomplikované. Oba jste dost agilní a svobodu milující na to, abyste se vyhnuli příliš vášnivé nebo intenzivní angažovanosti. Nicméně vnější lákadla to mohou všechno zničit.`,
  ariesvscancer: `VŮDCE A MATRIARCHA - Takové klasické protiklady, jako je beraní nezávislost a račí závislost, mohou nalézt něco podobného harmonii pouze ve velmi tradičním uspořádání, kde Beran bude mužem, vydělávajícím na chléb, a Rak ženou, udržující rodinný krb. Když se vám to nepovede, budou Beran svou sobeckostí a Rak svým strádáním pouze jeden druhého sužovat.`,
  ariesvsleo: `VŮDCE A VLADAŘ - Hodně toho můžete dosáhnout a užít si přitom spoustu legrace a vzrušení. Pokud se ale tato interakce změní v závod o to, kdo bude dominantní a kdo toho víc dosáhne, stane se problémem a může přejít v drama. Když ale oba soustředíte svou obrovskou energii na dosažení společného cíle a budete se řídit podobnými zásadami, pak půjde všechno hladce.`,
  ariesvsvirgo: `VŮDCE A RÁDCE - Pannin problém spočívá v tom, že Beran ji neposlouchá a vrhá se do všeho po hlavě, a pak možná začne poslouchat, až bude příliš pozdě. Takže Beran by se měl naučit naslouchat, pozorně zvažovat Panniny rady, a pak buď jednat - anebo ne. Panna se učí být energičtější, sebejistější při udělování svých rad a v neposlední řadě se učí podle nich také jednat.`,
  ariesvslibra: `VŮDCE A DIPLOMAT - Můžete fungovat jako tým, dokud bude Beranovi umožněno, aby si razil cestu vpřed svým přímočarým způsobem, zatímco Váhy budou urovnávat všechny problémy, které tím vzniknou. Příjemnost Vah a energičnost Berana mohou být v harmonii. Když ale neuznáte, jak jste rozdílní, můžete svou rozdílnost pociťovat jako neohrabanost a útlocitnost, která vás bude strašně rozčilovat.`,
  ariesvsscorpio: `VŮDCE A ŠPIÓN - Je to, jako když se potká oheň s ledem; zpočátku spousta vášnivého syčení a tání, ale vaše živelné povahy budou nevyhnutelně jedna druhou ohrožovat, což způsobí zuřivost a odpor. Štír začne s opovržením považovat beraní přímočarost za hloupost, a Beran nebude moci vystát skryté psychologické děje, probíhající ve Štírově podvědomí. Zde je nutná zcela zásadní upřímnost.`,
  ariesvssagittarius: `VŮDCE A KNĚZ - Zde se snoubí schopnost o něco v životě usilovat s oprávněností to získat. V důsledku toho máte prostředky dostat se daleko a hodně toho dosáhnout. Pokud to zní spíš jako společný podnik než vztah, pak jste si všimli, že cit pro intimní důvěrnost nemusí být zcela v pořádku - ale záleží na tom?`,
  ariesvscapricorn: `VŮDCE A PREZIDENT - Spolu jste potenciálně úspěšní, ale pravděpodobnější je, že jeden z vás se cítí nad tím druhým nadřazený - obvykle Kozoroh nad Beranem. Protože však ani jeden z vás nehodlá být poražen, nakonec pravděpodobně dojde ke vzpouře, odporu anebo konfliktu.Společný cíl - anebo nepřítel - by vám mohl pomoci se sjednotit.`,
  ariesvsaquarius: `VŮDCE A REFORMÁTOR - Toto je vztah, který to opravdu může dotáhnout daleko, dokáže věci změnit, zavést nové normy atd. Oba jste nezávislí a svobodu milující, takže vzájemně respektujete prostor a přání druhého. Nicméně i toto nepochybně skvělé a snadné spojení má svou stinnou stránku: můžete přehlížet to malé a nuzné dítě, které se skrývá v jednom nebo obou z vás.`,
  ariesvspisces: `VŮDCE A SPASITEL - Beran chce zvítězit, Ryby jsou připravené nastavit druhou tvář. Beran se pouští přímo do akce, Rybám je bližší pasivní odpor. Zpočátku se může zdát, že jeden z vás zachraňuje toho druhého, ale později přestane být jasné, kdo je vlastně zachráncem a kdo obětí. Je to případ tragického omylu v totožnosti - pokud ovšem oba nezničíte své osobní mýty.`,
  taurusvsaries: `Kompromisní - BANKÉŘ A VŮDCE - Vaše kritéria jsou velmi odlišná. Beran chápe život z hlediska postupování kupředu bez ohledu na cokoli; Býk z hlediska zvažování ceny a lpění na tom, co má. Kdybyste byli schopni setkat se v půli cesty, mohl by váš vztah uspokojit zároveň základní potřeby jednoho i touhu druhého jít dopředu. Ale jedno silné a jedno tvrdohlavé ego toho zpravidla nikdy nedosáhnou.`,
  taurusvstaurus: `Solidní - DVA BANKÉŘI - Doufejme, že jste do společného vztahu vykročili pravou nohou, protože jestli ne, lepší už to asi nebude. Proč? Protože je dvakrát tak nepravděpodobné, že se změní dva Býci než jeden! Ale díky Přírodě a jejím rytmům je pravděpodobné, že přitáhnete někoho anebo narazíte na něco, co vás přinutí se změnit. Jen tak budete skutečně vzkvétat.`,
  taurusvsgemini: `Rozpačitý - BANKÉŘ A ŠPRÝMAŘ - Váš vztah vyvolává představu Býka poklidně se pasoucího na svém poli, kterému najednou začne kolem hlavy poletovat a bzučet včela. Býk zajišťuje a je věrný, zatímco Blíženci brání tomu, aby byl život příliš usedlý. Oba potřebujete přesně to, co vám může poskytnout ten druhý, ale když to neuznáte a nepřijmete, ohrozí to Býkovu stabilitu i svobodu Blíženců.`,
  taurusvsCancer: `Klidný - BANKÉŘ A MATRIARCHA - Podobáte se trochu farmáři a jeho ženě; jde o přirozené, tradiční a produktivní uspořádání vztahu. Avšak budou přítomny i jiné staromódní prvky - jako panovačnost, žárlivost a klasické rozdělení rolí podle pohlaví, se všemi klady a zápory. Ty jsou však nutnou cenou, kterou je třeba zaplatit Přírodě za tuto spolehlivou kombinaci.`,
  taurusvsleo: `Obtížný - BANKÉŘ A VLADAŘ - Je to pevná a trvalá kombinace, ale ani se neobejde bez bouří. Je naprosto zásadní, abyste si uvědomili, co vztahu poskytuje druhý. Býk patrně zajišťuje "scénu" nebo stabilitu a Lev "drama" nebo vzrušení. Když na to nepřistoupíte, nebudete odměněni rozkoší ani blahobytem.`,
  taurusvsvirgo: `Příjemný - BANKÉŘ A RÁDCE - Je to velmi harmonická kombinace. Býk zajišťuje a Panna udržuje - a pokud Býk příliš zabředne do materiálních věcí, Panna ho laskavým a trpělivým způsobem nasměřuje k jemnějším věcem života. Býkovou úlohou pak je upozornit Pannu na les, když ho pro stromy nevidí.`,
  taurusvslibra: `Souhlasný - BANKÉŘ A DIPLOMAT - Protože oba rádi určujete postup a způsob, jak věci dělat, byl by zázrak, kdyby váš vztah někdy vykrystalizoval v přirozeném, emocionálním smyslu. Spíše vám vyhovuje uspořádání, kde je náhradou za cokoli hlubšího potěšení těla a společnost. Pokud vám to ale vyhovuje, můžete si užívat klidu a stability.`,
  taurusvsscorpio: `Mocný - BANKÉŘ A ŠPIÓN - Býk chce udržet věci stabilní a takové, jaké jsou; Štír chce proniknout k jejich skrytému emocionálnímu jádru. Země a Podsvětí se spojily, ale žárlivě si střeží svá vlastní království. Aby toto vášnivé spojení fungovalo, oba musí respektovat to, jak jsou rozdílní, a přitom závislí jeden na druhém.`,
  taurusvssagittarius: `Nepříznivý - BANKÉŘ A KNĚZ - Střelec se zpočátku Býku jeví jako nadějný kandidát, ale nepotrvá dlouho a Býk bude cítit zklamání, že Střelec nesplňuje jeho očekávání. Střelci Býk zpočátku připadá jako tolik potřebné bezpečné útočiště, ale postupně se začíná cítit Býkem omezován. Zdravá výměna je možná, jestliže to vaše rozdílné dorozumívací prostředky anebo hodnotové systémy dovolí.`,
  taurusvscapricorn: `Úspěšný - BANKÉŘ A PREZIDENT - Tvoříte stabilní, přičinlivý a nakonec i blahobytný pár, a společně si užíváte rozkoší těla. Oba vyznáváte životní styl, který je založený na moci, přičemž Kozoroh spouští projekty a Býk udržuje finanční prostředky. Dokud jeden z vás nezačne být nenasytný nebo přízemní, vydržíte spolu, spokojení a v bezpečí.`,
  taurusvsaquarius: `Nepřiměřený - BANKÉŘ A REFORMÁTOR - Jelikož Býk aktivně "investuje" do vztahu, má sklon chovat se diktátorsky, když Vodnář riskuje, jak má ve zvyku. Země a Vzduch spíše žijí vedle sebe než spolu, což se projevuje v odlišných prioritách - u Býka jsou to fyzické potřeby, u Vodnáře duchovní vize. Protože jste oba tvrdohlaví, tvrdošíjně lpíte na svém - většinou nadarmo.`,
  taurusvspisces: `Symbiotický - BANKÉŘ A SPASITEL - Spojuje se zde radost ze života a jistota úrodného ostrova v tajemném moři. Vzájemně si dáváte to, co ten druhý potřebuje. Ryby dostanou něco pevného, co je bude živit a držet na uzdě; Býk si zase bude vědom zázraků života. Pouze egoistické sklony jednoho - držet se v bezpečí - anebo druhého - být příliš roztěkaný - by mohly ukončit toto potenciálně úspěšné spojení.`,
  geminivsaries:
    "SVĚŽÍ DVA ŠPRÝMAŘI - Otázkou může být, kdo si vlastně s kým zahrává, protože oba ve vztahu kličkujete sem a tam. Dokud ani jeden z vás nebude toužit po něčem emocionálně hlubším a nebude věci zkoumat do hloubky, život může být svěžím vánkem. Ale pokud vás takové vyhýbání se oblasti srdce přestane uspokojovat, může se vánek změnit v ledovou vichřici. Prostě dva motýli.",
  geminivstaurus:
    "ROZPAČITÝ ŠPRÝMAŘ A BANKÉŘ - Váš vztah vyvolává představu Býka poklidně se pasoucího na svém poli, kterému najednou začne kolem hlavy poletovat a bzučet včela. Býk zajišťuje a je věrný, zatímco Blíženci brání tomu, aby byl život příliš usedlý. Oba potřebujete přesně to, co vám může poskytnout ten druhý, ale když to neuznáte a nepřijmete, ohrozí to Býkovu stabilitu i svobodu Blíženců.",
  geminivsgemini:
    "INTELIGENTNÍ DVA ŠPRÝMAŘI - Jste jako dvojčata, která si dokonale rozumějí, co se týče humoru, rychlého myšlení a nadhledu. Dokud ani jeden z vás nebude toužit po hlubším emočním propojení, je tento vztah svěží a zábavný. Ale pokud začne chybět hloubka, vzájemné pochopení se může rozpadnout.",
  geminivscancer:
    "NEZÁVAZNÝ ŠPRÝMAŘ A MONARCHA - Jste jako květ a plod, jeden musí strom opustit a druhý na něm musí zůstat, dokud nedozraje. Jste součástí stejného procesu, ale nevycházíte spolu snadno. Může to fungovat, dokud bude Blíženec buď pryč, anebo bude domů přicházet s novými názory anebo lidmi, zatímco Rak bude udržovat rodinný krb.",
  geminivsleo:
    "PŘÁTELSKÝ ŠPRÝMAŘ A VLADAŘ - Je to hravá interakce. Může se zdát, že je všechno podle Lva, ale ve skutečnosti je to Blížencův bystrý smysl pro humor, jeho láska ke změně a nestrannost, která je s tím spojena, co má někdy nad Lvem navrch.",
  geminivsvirgo:
    "ZNEKLIDŇUJÍCÍ ŠPRÝMAŘ A RÁDCE - Oba dva toho máte hodně co říct, ale protože každý z vás má jiné plány a jiné priority, v mnohém si nerozumíte. Panna přemýšlí prakticky, Blíženec myslí ve svém vlastním zájmu.",
  geminivslibra:
    "INTELIGENTNÍ ŠPRÝMAŘ A DIPLOMAT - Každý máte svůj vlastní způsob, jak obratně manipulovat věcmi, aby se zdály snadnější, než ve skutečnosti jsou. Navzájem se v tom podporujete do té míry, že věci začnou být skutečně snadnější, než by být měly!",
  geminivsscorpio:
    "NEOMALENÝ ŠPRÝMAŘ A ŠPIÓN - Blíženec věci zlehčuje, zatímco Štír jde do hloubky. Mohli byste se dohodnout, ale Štír vnímá lehkost Blíženců jako prostořekost a citovou neupřímnost.",
  geminivssagittarius:
    "PŘEKVAPUJÍCÍ ŠPRÝMAŘ A KNĚZ - Blížencův bystrý intelekt může Střelci pomoci od pobožnůstkářství a nedostatku informovanosti, zatímco Střelec může Blíženci nabídnout celkový obraz.",
  geminivscapricorn:
    "BLAHOSKLONNÝ ŠPRÝMAŘ A PREZIDENT - Na úrovni materiální je Kozoroh nekonečně zkušenější a schopnější než Blíženec, který jej toleruje, protože mu Kozoroh poskytuje informace a zábavu.",
  geminivsaquarius:
    "INTELEKTUÁLNÍ ŠPRÝMAŘ A REFORMÁTOR - Oba jste naladěni na stejné vlnové délce, život chápete z duševního hlediska, nekonečné slovní hříčky a abstraktní pojmy spřádáte do látky, kterou oba shodně považujete za realitu.",
  geminivspisces:
    "PŘIZPŮSOBIVÝ ŠPRÝMAŘ A SPASITEL - Na esoterické úrovni jste oba spřízněni, naladěni na pravdu, kterou se dotýkáme absolutna, skrze směs humoru a pokory.",
  cancervsaries: `MATRIARCHA A VŮDCE - Takové klasické protiklady, jako je beraní nezávislost a račí závislost, mohou nalézt něco podobného harmonii pouze ve velmi tradičním uspořádání, kde Beran bude mužem, vydělávajícím na chléb, a Rak ženou, udržující rodinný krb. Když se vám to nepovede, budou Beran svou sobeckostí a Rak svým strádáním pouze jeden druhého sužovat.`,
  cancervstaurus: `MATRIARCHA A BANKÉŘ - Podobáte se trochu farmáři a jeho ženě; jde o přirozené, tradiční a produktivní uspořádání vztahu. Avšak budou přítomny i jiné staromódní prvky - jako panovačnost, žárlivost a klasické rozdělení rolí podle pohlaví, se všemi klady a zápory. Ty jsou však nutnou cenou, kterou je třeba zaplatit Přírodě za tuto spolehlivou kombinaci.`,
  cancervsgemini: `MATRIARCHA A ŠPRÝMAŘ - Jste jako květ a plod, jeden musí strom opustit a druhý na něm musí zůstat, dokud nedozraje. Jste součástí stejného procesu, ale nevycházíte spolu snadno. Může to fungovat, dokud bude Blíženec buď pryč, anebo bude domů přicházet s novými názory anebo lidmi, zatímco Rak bude udržovat rodinný krb. Ale pokud začne být Rak příliš závislý, Blíženec se domů nemusí vrátit vůbec.`,
  cancervscancer: `DVA MATRIARCHOVÉ - Vaše instinktivní potřeba pocitu bezpečí, společně s vřelým a důvěrným chováním, svědčí o tom, že jste přirozenými a pravými budovateli hnízda a rodiny. Ale jak už to u kombinací stejných znamení bývá, můžete z nich mít to nejlepší, ale i to nejhorší. Ve vašem případě vám hrozí, že se budete navzájem rozmazlovat do té míry, až začnete ztrácet ze zřetele jeden druhého jako individuálního jedince.`,
  cancervsleo: `MATRIARCHA A VLADAŘ - Lev přináší jiskru do Rakova na bezpečí orientovaného a možná trochu omezeného života; Rak poskytuje rodinné zázemí. Pokud vám tato výměna nevyhovuje, začne se Lev cítit takovou důvěrností tísněn, Rak zase může cítit odpor ke lví lásce ke vzrušení, protože se jí cítí ohrožen.`,
  cancervsvirgo: `MATRIARCHA A RÁDCE - Jste "miláčci Matky Přírody" v tom, že společně vytváříte útulné, dobře fungující a starostlivé prostředí, ať už doma nebo kdekoli jinde. Ovšem v negativním případě může být tato atmosféra tak hustá, že se v ní začnete dusit. Příležitostný výlet by mohl vyrovnat "riziko přílišného bezpečí" této skvělé kombinace.`,
  cancervslibra: `MATRIARCHA A DIPLOMAT - Rak potřebuje bezpečí a Váhy chtějí klid, což je dobrý základ do začátku. Ale zatímco bezpečí se udržuje tím, že se věci ovládají, klid se hledá tak, že se věci odhalují - a v tom si nemusíte rozumět. Abyste dosáhli harmonie a pohodlí, musíte vzájemně tyto své role respektovat.`,
  cancervsscorpio: `MATRIARCHA A ŠPIÓN - Můžete spolu fungovat velmi dobře, pokud se shodnete na citových prioritách a nepodlehnete dojmu, že byste měli být jeden pro druhého vším - dojmu, který zpočátku budíte i přijímáte. Měli byste to vyřešit co nejdřív, protože jako hluboce emocionální bytosti byste později mohli zjistit, že vám chybí jakýkoli prostor či nálada pro vyjednávání.`,
  cancervssagittarius: `MATRIARCHA A KNĚZ - Domov a otevřená cesta skutečně nejdou příliš dohromady, ledaže byste bydleli v obytném přívěsu. Rak tíhne k bezpečí a důvěrnosti, zatímco Střelec usiluje o vzdálené horizonty. Pro Raka je Střelec ztělesněná nejistota. Pro Střelce je Rak jako otevřené vězení. Pokud nedokážete být otevřenější anebo cikánštější, vaše rozdílné hodnoty vás oddělí.`,
  cancervscapricorn: `MATRIARCHA A PREZIDENT - V ideálním případě můžete vytvořit "dokonalou" kombinaci, kde se Kozoroh bude starat o světské záležitosti a Rak dohlédne na ty domácí, cílem bude rodina a dobrá pověst. Všechno bude jasné, když přijmete fakt, že Rak upřednostňuje city a Kozoroh praktičnost - a když si občas jeden z druhého vezmete příklad.`,
  cancervsaquarius: `MATRIARCHA A REFORMÁTOR - Zpravidla jsou vaše hodnoty a cíle příliš odlišné na to, aby šly spojit. Rak chce udržet status quo; Vodnář ho chce změnit. Rak pochází z břicha, Vodnář z hlavy. Skutečnost, že mezi vámi vůbec nějaká interakce probíhá, nasvědčuje tomu, že se potřebujete jeden od druhého učit - jinak je to katastrofa!`,
  cancervspisces: `MATRIARCHA A SPASITEL - Toto je taková kombinace, jakých svět potřebuje co nejvíc! Hlavní oporou je zde vaše schopnost sladit se vzájemně se svými pocity, sny a obavami a respektovat je. Navíc tuto sympatii a soucit úspěšně vyzařujete na svou rodinu, přátele a svět obecně. Dejte si ale pozor, abyste jeden druhému dovolili respektovat i své vlastní sny.`,
  leovsaries: `BERAN - Hrdinský VLADAŘ A VŮDCE - Hodně toho můžete dosáhnout a užít si přitom spoustu legrace a vzrušení. Pokud se ale tato interakce změní v závod o to, kdo bude dominantní a kdo toho víc dosáhne, stane se problémem a může přejít v drama. Když ale oba soustředíte svou obrovskou energii na dosažení společného cíle a budete se řídit podobnými zásadami, pak půjde všechno hladce.`,
  leovstaurus: `BÝKA - Obtížný VLADAŘ A BANKÉŘ - Je to pevná a trvalá kombinace, ale ani se neobejde bez bouří. Je naprosto zásadní, abyste si uvědomili, co vztahu poskytuje druhý. Býk patrně zajišťuje "scénu" nebo stabilitu a Lev "drama" nebo vzrušení. Když na to nepřistoupíte, nebudete odměněni rozkoší ani blahobytem.`,
  leovsgemini: `BLÍŽENCI - Přátelský VLADAŘ A ŠPRÝMAŘ - Je to hravá interakce. Může se zdát, že je všechno podle Lva, ale ve skutečnosti je to Blížencův bystrý smysl pro humor, jeho láska ke změně a nestrannost, která je s tím spojena, co má někdy nad Lvem navrch. Celkově je to dost hluboká interakce, protože plodí tiché porozumění, založené na lví síle a blíženecké inteligenci.`,
  leovscancer: `RAK - Dramatický VLADAŘ A MATRIARCHA - Lev přináší jiskru do Rakova na bezpečí orientovaného a možná trochu omezeného života; Rak poskytuje rodinné zázemí. Pokud vám tato výměna nevyhovuje, začne se Lev cítit takovou důvěrností tísněn, Rak zase může cítit odpor ke lví lásce ke vzrušení, protože se jí cítí ohrožen.`,
  leovsleo: `LEV - Zdvořilý DVA VLADAŘI - Vaše interakce je "zdvořilá" spíše z povinnosti než z přirozenosti. Když si nevymezíte své oblasti vládnutí, například kdo bude mít vládu nad domovem, financemi, dětmi, pak váš prudký boj o místo na slunci povede k slzám a sváru, anebo k životu v různých "královstvích". Spravedlivě rozdělte, "kdo čemu vládne", a pak ctěte pravidla!`,
  leovsvigo: `PANNA - Delikátní VLADAŘ A RÁDCE - Tato interakce může fungovat, pokud Lev připustí, že potřebuje někoho, komu může věřit, že ho bude vždy informovat o tom, na co si má dát pozor. Na oplátku věnuje Lev Panně tolik potřebnou důvěru a učiní z ní vlivnou osobu v pozadí. Ale když bude Panna své moci zneužívat, může upadnout v nemilost - dokonce může být zapuzena - ale Lev toho může litovat.`,
  leovslibra: `VÁHY - Vlídný VLADAŘ A DIPLOMAT - Měla by to být docela vlídná interakce, protože Váhy se podrobují lví vůli a Lev oceňuje společenský takt Vah, hlavně jejich schopnost urovnat problémy, vzniklé v důsledku vladařových faux pas. Váhy milují pocit, že jsou součástí něčeho velkého a důstojného. Ale měly by si dávat pozor na pocit bezmocnosti, Lev zase na pocit frustrace.`,
  leovsscorpio: `ŠTÍR - Nebezpečný VLADAŘ A ŠPIÓN - Tato mocná znamení mohou být v žárlivém sporu. Aby se konflikt zmírnil, měl by Lev to, co odsuzuje jako štíří pokoutnost, chápat spíše jako psychologické uvědomění, které se neobejde bez lví šlechetnosti ducha, zatímco Štír by měl to, čím opovrhuje jako lví svévolí, považovat pouze za naivitu, která potřebuje hluboký štíří vhled.`,
  leovsstarch: `STŘELEC - Velkodušný VLADAŘ A KNĚZ - Oba máte své "státnické záležitosti", které vás zaměstnávají, takže váš společný život se může podobat slavnostnímu průvodu, se vší zábavou a barevností, kterou představuje. Oba jste "velká" znamení, takže si můžete užívat života ve velkém stylu, ale abyste zabránili odcizení, neměli byste zapomínat ani na "drobné" věci, jako je takt a skrytá nejistota.`,
  leovscapricornius: `KOZOROH - Pragmatický VLADAŘ A PREZIDENT - Oba rádi zachováváte určitý formalismus a společenské konvence, protože udržují vládu a pořádek, jež milujete. Nicméně budete potřebovat trpělivost a víru, abyste mohli komunikovat s citlivou duší, která se skrývá v každém z vás pod maskou moci. Pokud ji neobjevíte, vztahy budou zcela určitě ledové.`,
  leovsaquarius: `VODNÁŘ - Reaktivní VLADAŘ A REFORMÁTOR - Pro tento protiklad je nejtěžší se (opětovně) spojit, ale je to také nejdůležitější. A to proto, že představuje propast mezi privilegovanými a prostými, která způsobuje většinu nemocí a špatností světa. Až srdce Lva bude ušlechtilé a velkorysé a mysl Vodnáře poctivá a pravdivá - tehdy, a jenom tehdy, zavládne skutečný mír.`,
  leovspisces: `RYBY - Ohleduplný VLADAŘ A SPASITEL - Ryba, která nastavuje druhou tvář, může budit dojem, že dává lvu volnou ruku, aby vládl podle libosti. Ale po určité době se ukáže, že Ryby sledují svůj vlastní cíl, který Lva zákeřně ohrožuje. Lev udělá nejlépe, když bude Ryby chápat jako příklad moci bezmocných, a Ryby by zase měly považovat Lva za vzorový příklad toho, že každý si nakonec sní to, co si nadrobil.`,
  virgovsaries: `BERAN - Omezený\nRÁDCE A VŮDCE - Pannin problém spočívá v tom, že Beran ji neposlouchá a vrhá se do všeho po hlavě, a pak možná začne poslouchat, až bude příliš pozdě. Takže Beran by se měl naučit naslouchat, pozorně zvažovat Panniny rady, a pak buď jednat - anebo ne. Panna se učí být energičtější, sebejistější při udělování svých rad a v neposlední řadě se učí podle nich také jednat.`,
  virgovstaurus: `BÝKA - Příjemný\nRÁDCE A BANKÉŘ - Je to velmi harmonická kombinace. Býk zajišťuje a Panna udržuje - a pokud Býk příliš zabředne do materiálních věcí, Panna ho laskavým a trpělivým způsobem nasměřuje k jemnějším věcem života. Býkovou úlohou pak je upozornit Pannu na les, když ho pro stromy nevidí.`,
  virgovsgemini: `BLÍŽENCI - Zneklidňující\nRÁDCE A ŠPRÝMAŘ - Oba dva toho máte hodně co říct, ale protože každý z vás má jiné plány a jiné priority, v mnohém si nerozumíte. Panna přemýšlí prakticky, Blíženec myslí ve svém vlastním zájmu. A při všem tom myšlení a mluvení zbývá jen málo místa pro nějakou skutečnou citovou souhru. Přesto se můžete jeden od druhého hodně naučit, a také si užít spoustu legrace.`,
  virgovscancer: `RAK - Přirozený\nRÁDCE A MATRIARCHA - Jste "miláčci Matky Přírody" v tom, že společně vytváříte útulné, dobře fungující a starostlivé prostředí, ať už doma nebo kdekoli jinde. Ovšem v negativním případě může být tato atmosféra tak hustá, že se v ní začnete dusit. Příležitostný výlet by mohl vyrovnat "riziko přílišného bezpečí" této skvělé kombinace.`,
  virgovsleo: `LEV - Delikátní\nRÁDCE A VLADAŘ - Tato interakce může fungovat, pokud Lev připustí, že potřebuje někoho, komu může věřit, že ho bude vždy informovat o tom, na co si má dát pozor. Na oplátku věnuje Lev Panně tolik potřebnou důvěru a učiní z ní vlivnou osobu v pozadí. Ale když bude Panna své moci zneužívat, může upadnout v nemilost - dokonce může být zapuzena - ale Lev toho může litovat.`,
  virgovsvirgo: `PANNA - Kritický\nDVA RÁDCOVÉ - Protože znamení Panny tolik miluje zdravost a rozumnost, tato kombinace může být přepjatost sama! Všechno se kontroluje a prohlíží, zařizuje se i to, co zařídit nepotřebuje, až je život samá příprava a žádné prožívání. Věčná kostýmová zkouška. Avšak i pokud se s tím vyrovnáte, bude z vašeho společného úsilí a preciznosti ve skutečnosti těžit někdo jiný.`,
  virgovslibra: `VÁHY - Puntičkářský\nRÁDCE A DIPLOMAT - Protože oba dva máte jasnou představu, jak by se měly věci dělat, můžete spolu velmi dobře vycházet - zpočátku. Nakonec však bude váš život tak "správný", že chaotičtější a komplikovanější emoce, které jsou realitou skutečného vztahu, vykážete do třinácté komnaty. Pomohlo by, kdybyste je pravidelně a společně provětrali.`,
  virgovsscorpio: `ŠTÍR - Svízelný\nRÁDCE A ŠPIÓN - Rozvážnost Panny může Štíra naučit moudrosti nic nepřehánět, zatímco štíří emocionální vhled může Panně pomoci, aby nebyla tak svatouškovská. Ale tato výměna bude fungovat pouze tehdy, když budete oba vědomě s tímto "obchodem" souhlasit. A i když souhlasit budete, může vás taková vzájemná očista oba vyčerpat.`,
  virgovssagittarius: `STŘELEC - Nešťastný\nRÁDCE A KNĚZ - To, co začíná jako Pannin obdiv ke Střelcovu optimismu a štědrosti, se může proměnit ve vyloženou zlost, když se jeho sliby nerozplynou. Na to všechno Střelec reaguje jen povzdechem nebo dalším škádlením. Aby tato interakce fungovala, museli byste si uvědomit, že Pannin smysl pro detail a Střelcova schopnost vnímat celek se mohou navzájem doplňovat.`,
  virgovscapricorn: `KOZOROH - Dobře fungující\nRÁDCE A PREZIDENT - Je to klasické - kde by byl jeden bez druhého? Úspěch nakonec závisí na tom, aby každý znal své pole působnosti - něco, v čem oba vynikáte. Ale přitom, jak kategorizujete a škatulkujete, nezapomeňte si udělat čas a prostor pro trochu pozemské zábavy a nesmyslů - pak si budete dobře žít ve více směrech než pouze v jednom.`,
  virgovsaquarius: `VODNÁŘ - Idiosynkratická\nRÁDCE A REFORMÁTOR - Oba dva jste vysoce individualističtí, což může být vaše zhouba nebo dobrodiní. Zhouba - jestliže si myslíte, že byste měli být stejný typ jedince, což je logický protimluv, který způsobí soustavné zhoršování situace. Dobrodiní - pokud poskytnete jeden druhému prostor a čas potřebný k tomu, abyste nalezli sami sebe a byli více dvěma jedinečnými lidskými bytostmi než dvojicí.`,
  virgovspisces: `RYBY - Prostý\nRÁDCE A SPASITEL - Vy dva můžete jeden druhému skutečně pomoci zakusit citlivost spojenou s řádem. Musíte se ale vyhnout pasti, která spočívá v tom, že Pannino zaměření na detail postrádá cit pro věc, a že Ryby na to reagují přehnaně. Máte stejnou představu o tom, jak dobrý by měl život být - jen si uvědomte, že ji oba vnímáte a přistupujete k ní z protichůdných hledisek.`,
  libravsaries:
    "Konfrontační DIPLOMAT A VŮDCE - Můžete fungovat jako tým, dokud bude Beranovi umožněno, aby si razil cestu vpřed svým přímočarým způsobem, zatímco Váhy budou urovnávat všechny problémy, které tím vzniknou. Příjemnost Vah a energičnost Berana mohou být v harmonii. Když ale neuznáte, jak jste rozdílní, můžete svou rozdílnost pociťovat jako neohrabanost a útlocitnost, která vás bude strašně rozčilovat.",
  libravstaurus:
    "Souhlasný DIPLOMAT A BANKÉŘ - Protože oba rádi určujete postup a způsob, jak věci dělat, byl by zázrak, kdyby váš vztah někdy vykrystalizoval v přirozeném, emocionálním smyslu. Spíše vám vyhovuje uspořádání, kde je náhradou za cokoli hlubšího potěšení těla a společnost. Pokud vám to ale vyhovuje, můžete si užívat klidu a stability.",
  libravsgemini:
    "Inteligentní DIPLOMAT A ŠPRÝMAŘ - Každý máte svůj vlastní způsob, jak obratně manipulovat věcmi, aby se zdály snadnější, než ve skutečnosti jsou. Navzájem se v tom podporujete do té míry, že věci začnou být skutečně snadnější, než by být měly! Dokud budete oba spokojeni s tak intelektuálním životem a láskou, bez hlubokých citů, všechno bude dobré.",
  libravscancer:
    "Opatrný DIPLOMAT A MATRIARCHA - Rak potřebuje bezpečí a Váhy chtějí klid, což je dobrý základ do začátku. Ale zatímco bezpečí se udržuje tím, že se věci ovládají, klid se hledá tak, že se věci odhalují - a v tom si nemusíte rozumět. Abyste dosáhli harmonie a pohodlí, musíte vzájemně tyto své role respektovat.",
  libravsleo:
    "Vlídný DIPLOMAT A VLADAŘ - Měla by to být docela vlídná interakce, protože Váhy se podrobují lví vůli a Lev oceňuje společenský takt Vah, hlavně jejich schopnost urovnat problémy, vzniklé v důsledku vladařových faux pas. Váhy milují pocit, že jsou součástí něčeho velkého a důstojného. Ale měly by si dávat pozor na pocit bezmocnosti, Lev zase na pocit frustrace.",
  libravsvirgo:
    'Puntičkářský DIPLOMAT A RÁDCE - Protože oba dva máte jasnou představu, jak by se měly věci dělat, můžete spolu velmi dobře vycházet - zpočátku. Nakonec však bude váš život tak "správný", že chaotičtější a komplikovanější emoce, které jsou realitou skutečného vztahu, vykážete do třinácté komnaty. Pomohlo by, kdybyste je pravidelně a společně provětrali.',
  libravslibra:
    "Uctivý DVA DIPLOMATÉ - Octli jste se tváří v tvář nutnosti vědět, jak reagovat a komunikovat v nebezpečných situacích, a jak se obecně společensky chovat. Pokud vám to jde, jste buď výjimečně taktní a dobře vychovaní, anebo jste povrchní na úkor emocionální upřímnosti. Anebo něco mezi tím. Rozhodnutí je na vás!",
  libravscorpio:
    "Náročný DIPLOMAT A ŠPIÓN - Je víc než pravděpodobné, že nevědomky pracujete proti sobě, Váhy si totiž přejí poctivý a úctyhodný protějšek, ale Štír touží po něčem hlubším a temnějším. Příjemné a přátelské chování Vah vnímá Štír jako povrchní a kýčovité, a proto s ním Váhy posléze jednají v rukavičkách, což způsobí, že je Štír ještě zatvrzelejší. Buďte upřímní - ale také spravedliví.",
  libravsagittarius:
    "Rozumný DIPLOMAT A KNĚZ - Oba jste mistři v pozorování norem společnosti, v níž žijete, takže úspěšně vedete svůj vztah ve shodě s jejich psanými i nepsanými zákony. Někdy to znamená, že oba zapojujete svou hlavu spíše než srdce, což může redukovat vášeň - ale to je cena, kterou platíte za pořádek.",
  libravscapricorn:
    'Formální DIPLOMAT A PREZIDENT - Je to velmi "korektní" spojení, které neposkytuje mnoho prostoru pro velkou vášeň nebo nekonvenčnost. Vzhledem k vašemu konvenčnímu stylu jste schopni vybudovat a zformovat slušný společný život. Ale pokud kterýkoli z vás začne jevit známky nespokojenosti, pak je čas začít si city více uvědomovat a projevovat.',
  libravsaquarius:
    "Hloubavý DIPLOMAT A REFORMÁTOR - Kdybyste se trochu rozhýbali, mohli byste dosáhnout velkých věcí, a dokonce vykonat pro společnost nějakou pionýrskou práci. Mohli byste se stát pro druhé příkladem toho, jak mohou dva lidé žít v harmonii jako pár a přitom zůstat plnohodnotnými jedinci - nejdřív byste museli sestoupit ze svých hlav do svých těl - přejít od teorie k praxi.",
  libravspisces:
    "Vlídný DIPLOMAT A SPASITEL - Nerozhodnost Vah a vyhýbavost Ryb mohou budit zdání kompatibility, zdání, že se k sobě dobře hodíte, protože ani jeden z vás nechce čelit temným či obtížným věcem. Ale pokud se skutečně rozhodnete vést poctivý vztah, dělejte tak s upřímností a citlivostí - jinak se může stát pouhým přeludem.",
  scorpiovsaries:
    "ŠPIÓN A VŮDCE - Je to, jako když se potká oheň s ledem; zpočátku spousta vášnivého syčení a tání, ale vaše živelné povahy budou nevyhnutelně jedna druhou ohrožovat, což způsobí zuřivost a odpor. Štír začne s opovržením považovat beraní přímočarost za hloupost, a Beran nebude moci vystát skryté psychologické děje, probíhající ve Štírově podvědomí. Zde je nutná zcela zásadní upřímnost.",
  scorpiovstaurus:
    "ŠPIÓN A BANKÉŘ - Býk chce udržet věci stabilní a takové, jaké jsou; Štír chce proniknout k jejich skrytému emocionálnímu jádru. Země a Podsvětí se spojily, ale žárlivě si střeží svá vlastní království. Aby toto vášnivé spojení fungovalo, oba musí respektovat to, jak jsou rozdílní, a přitom závislí jeden na druhém.",
  scorpiovsgemini:
    "ŠPIÓN A ŠPRÝMAŘ - Blíženec věci zlehčuje, zatímco Štír jde do hloubky. Mohli byste se dohodnout, ale Štír vnímá lehkost Blíženců jako prostořekost a citovou neupřímnost. Blíženec považuje Štírovu hloubku za falešnou a obtížnou, takže se vykrucuje ještě víc. Může dojít ke zvláštním milostným pletkám, ale rozhodně to nebude klidný svazek.",
  scorpiovscancer:
    "ŠPIÓN A MATRIARCHA - Můžete spolu fungovat velmi dobře, pokud se shodnete na citových prioritách a nepodlehnete dojmu, že byste měli být jeden pro druhého vším - dojmu, který zpočátku budíte i přijímáte. Měli byste to vyřešit co nejdřív, protože jako hluboce emocionální bytosti byste později mohli zjistit, že vám chybí jakýkoli prostor či nálada pro vyjednávání.",
  scorpiovsleo:
    "ŠPIÓN A VLADAŘ - Tato mocná znamení mohou být v žárlivém sporu. Aby se konflikt zmírnil, měl by Lev to, co odsuzuje jako štíří pokoutnost, chápat spíše jako psychologické uvědomění, které se neobejde bez lví šlechetnosti ducha, zatímco Štír by měl to, čím opovrhuje jako lví svévolí, považovat pouze za naivitu, která potřebuje hluboký štíří vhled.",
  scorpiovsvirgo:
    "ŠPIÓN A RÁDCE - Rozvážnost Panny může Štíra naučit moudrosti nic nepřehánět, zatímco štíří emocionální vhled může Panně pomoci, aby nebyla tak svatouškovská. Ale tato výměna bude fungovat pouze tehdy, když budete oba vědomě s tímto 'obchodem' souhlasit. A i když souhlasit budete, může vás taková vzájemná očista oba vyčerpat.",
  scorpiovslibra:
    "ŠPIÓN A DIPLOMAT - Je víc než pravděpodobné, že nevědomky pracujete proti sobě, Váhy si totiž přejí poctivý a úctyhodný protějšek, ale Štír touží po něčem hlubším a temnějším. Příjemné a přátelské chování Vah vnímá Štír jako povrchní a kýčovité, a proto s ním Váhy posléze jednají v rukavičkách, což způsobí, že je Štír ještě zatvrzelejší. Buďte upřímní - ale také spravedliví.",
  scorpiovsscorpio:
    "DVA ŠPIÓNI - Rozumíte jeden druhému, protože oba obýváte stejný svět hlubokých citů a temných tajemství. Jestliže se dokážete vyhnout přízraku zrady, který ohrožuje nepostradatelnou důvěru, pak bude váš svazek trvalý a nepochybný. Bylo by moudré vzájemně kontrolovat/respektovat své slabiny, dokud riziko nepomine.",
  scorpiovsagittarius:
    "ŠPIÓN A KNĚZ - Oba milujete moc, ale zatímco Střelec ji projevuje otevřeně, Štír ji používá skrytě. Vaše definice pravdy jsou velmi odlišné. Proto je pro vás těžké číst jeden v druhém, z čehož plynou rozpaky a vytáčky. Důvod, proč jste spolu, je pro střelce nutnost naučit se trochu taktnosti a pro Štíra otevřenosti. Pokud ne, bude to pouhá 'paranoia'.",
  scorpiovscapricorn:
    "ŠPIÓN A PREZIDENT - Můžete být jeden pro druhého velmi užiteční. Nezní to příliš romanticky, a ani nemůže, protože jste věcný, praktický pár. Přesto je úkolem Štíra připomenout Kozorohu, že je koneckonců emocionální bytost, zatímco Kozoroh má Štíra naučit, že zneužívá své emocionální svody na vlastní nebezpečí. Je to mocná dvojice, v dobrém anebo ve zlém.",
  scorpiovsaquarius:
    "ŠPIÓN A REFORMÁTOR - Postupujete tak rozdílně, že snadno jeden druhého zmatete. Štír chce intriky a citové uspokojení; Vodnář má sklon spíše odhalovat 'pravdu' a tíhnout k věcem, které dávají smysl. Pokud navzájem neuznáte oprávněnost svých požadavků, budete oba podráždění.",
  scorpiovspisces:
    "ŠPIÓN A SPASITEL - Váš svazek je silný, ale zvláštní. Váš vztah obsahuje hluboké a tajemné prvky, které se odhalí pouze tehdy, až se čas naplní - a možná ani tehdy ne docela. Protože jste oba intuitivní a citoví, jste naladěni na tento skrytý proces a jste věrní jemu i jeden druhému - tedy s výjimkou občasných úskalí.",

  sagittariusvsaries: `Podnikavý - Střelec a Beran mají silnou vzájemnou dynamiku, obě znamení jsou plná energie a touhy po dobrodružství. Mohou společně dosáhnout mnohého, i když je zde někdy napětí kvůli jejich silným osobnostem. Vzájemné porozumění je klíčové pro jejich úspěch.`,
  sagittariusvstaurus: `Nepříznivý - Střelec a Býk se potýkají s rozdílnými hodnotami a přístupy k životu. Býk hledá stabilitu a bezpečí, zatímco Střelec touží po volnosti a změnách, což může vést k frustraci a napětí.`,
  sagittariusvsgemini: `Překvapující - Tato kombinace může být velmi obohacující. Blíženci mohou nabídnout Střelci intelektuální stimulaci a flexibilitu, zatímco Střelec poskytuje širší perspektivu a filozofii, která pomůže Blížencům spojit jejich roztěkané myšlenky.`,
  sagittariusvscancer: `Nevhodný - Rak a Střelec se rozcházejí v základních hodnotách. Rak touží po bezpečí a intimnosti, zatímco Střelec hledá nové horizonty. Pokud nebudou schopni se přizpůsobit a otevřít, mohou se cítit odděleně.`,
  sagittariusvsleo: `Velkodušný - Střelec a Lev tvoří silný a energický pár, kde oba mají velké plány a společně si užívají život ve velkém stylu. Pokud se budou zaměřovat na drobné detaily a vzájemně respektovat svou roli, mohou vytvořit skvělý tým.`,
  sagittariusvsvirgo: `Nešťastný - Panna může být zklamána Střelcovým optimismem a nesplněnými sliby, zatímco Střelec reaguje na Panniny kritiky s nezájmem. Aby tento vztah fungoval, museli by si být vědomi svých rozdílů a vzájemně se doplňovat.`,
  sagittariusvslibra: `Rozumný - Váhy a Střelec mohou tvořit vyvážený pár, který se dobře přizpůsobuje normám společnosti. I když jejich vztah může postrádat vášeň, mohou dosáhnout stabilního a harmonického partnerství, pokud si vzájemně budou naslouchat.`,
  sagittariusvsscorpio: `Podezíravý - Střelec a Štír mají rozdílné přístupy k moci a pravdě. Štír je tajemný a tajně manipuluje, zatímco Střelec otevřeně projevuje svou sílu. Pokud nebudou otevření a upřímní, vztah může být plný nedorozumění a konfliktů.`,
  sagittariusvsagittarius: `Idealistický - Když se dva Střelci spojí, mají silnou vzájemnou víru a snahu dosahovat společné cíle. I když se jejich cesty mohou lišit, oba jsou připraveni jít společně vpřed, motivováni svou touhou po dobrodružství a růstu.`,
  sagittariusvscapricorn: `Konkurenční - Střelec a Kozoroh mohou mít problém s vzájemným porozuměním. Kozoroh je pragmatický a soustředěný na cíle, zatímco Střelec je spíše idealistický a nezávislý. I když mohou být konkurenti, jejich kombinace může být silná, pokud se zaměří na společné cíle.`,
  sagittariusvsaquarius: `Liberální - Střelec a Vodnář mají podobné pohledy na svobodu a nezávislost. Oba si užívají výzvy a novinky a jejich vztah může být velmi inspirující, pokud se vyhnou slepému fanatismu a budou respektovat osobní svobodu toho druhého.`,
  sagittariusvspisces: `Ošidný - Střelec a Ryby se mohou vzájemně přitahovat díky svým ideálům a víře. Mnoho společného mají v oblasti vize a představ, ale pokud se nezaměří na praktické otázky, mohou si svou nezodpovědností a přehnaným optimismem škodit.`,

  capricornvsaries:
    "Konfliktní - Společný cíl by vám mohl pomoci se sjednotit, ale pravděpodobně dojde ke vzpouře, odporu nebo konfliktu. Kozoroh může být nad Beranem považován za nadřazeného.",
  capricornvstaurus:
    "Úspěšný - Tvoříte stabilní, přičinlivý pár, kde Kozoroh spouští projekty a Býk udržuje finanční prostředky. Vydržíte spolu, pokud nezačnete být nenasytní.",
  capricornvsgemini:
    "Blahosklonný - Kozoroh poskytuje Blížencům informace a zábavu, ale Blíženec může považovat Kozoroha za nudného. Vzájemné poznání by pomohlo.",
  capricornvscancer:
    "Vzájemně se doplňující - Kozoroh se stará o světské záležitosti a Rak o domácí. Když si vezmete příklad jeden od druhého, můžete tvořit dokonalý pár.",
  capricornvsleo:
    "Pragmatický - Oba chcete udržet vládu a pořádek, ale potřebujete trpělivost a víru, abyste komunikovali se skrytými citlivými stránkami osobnosti.",
  capricornvsvirgo:
    "Dobře fungující - Úspěch závisí na tom, aby každý znal své pole působnosti. Nezapomeňte na pozemskou zábavu a čas pro sebe.",
  capricornvslibra:
    "Formální - Vztah je korektní a bez velké vášně, ale umožňuje vybudovat stabilní život. Pokud se objeví nespokojenost, je čas projevit city.",
  capricornvsscorpio:
    "Prospěšný - Kozoroh a Štír mohou být velmi užiteční jeden pro druhého. Štír připomíná Kozorohovi jeho emocionální stránku, zatímco Kozoroh učí Štíra ovládat emocionální manipulace.",
  capricornvsagittarius:
    "Konkurenční - Oba chcete být šéfem, což může vést k hádkám. S kombinací vizí a praktičnosti byste mohli společně dosáhnout velkých věcí, ale lačnost po moci je problém.",
  capricornvscapricorn:
    "Neokázalý - Kvalitu vztahu měříte společenským postavením, které jste spolu dosáhli. Pokud objevíte vzájemně své duše a srdce, čeká vás úspěch.",
  capricornvsaquarius:
    "Taktický - Kozoroh a Vodnář mohou mít problém s rozdílnými sklony, ale interakce naznačuje, že Kozoroh se potřebuje zmodernizovat a Vodnář by měl dostat realitu.",
  capricornvspisces:
    "Slibný - Pokud Kozoroh uzná hodnotu Rybí citlivosti a Ryby přiznají praktickou stránku Kozoroha, může to vést k harmonickému spojení, připomínajícímu setkání Nebe se Zemí.",

  aquariusvsaries:
    "REFORMÁTOR A VŮDCE - Toto je vztah, který to opravdu může dotáhnout daleko, dokáže věci změnit, zavést nové normy atd. Oba jste nezávislí a svobodu milující, takže vzájemně respektujete prostor a přání druhého. Nicméně i toto nepochybně skvělé a snadné spojení má svou stinnou stránku: můžete přehlížet to malé a nuzné dítě, které se skrývá v jednom nebo obou z vás.",
  aquariusvstaurus:
    "REFORMÁTOR A BANKÉŘ - Jelikož Býk aktivně 'investuje' do vztahu, má sklon chovat se diktátorsky, když Vodnář riskuje, jak má ve zvyku. Země a Vzduch spíše žijí vedle sebe než spolu, což se projevuje v odlišných prioritách - u Býka jsou to fyzické potřeby, u Vodnáře duchovní vize. Protože jste oba tvrdohlaví, tvrdošíjně lpíte na svém - většinou nadarmo.",
  aquariusvsgemini:
    "REFORMÁTOR A ŠPRÝMAŘ - Oba jste naladěni na stejné vlnové délce, život chápete z duševního hlediska, nekonečné slovní hříčky a abstraktní pojmy spřádáte do látky, kterou oba shodně považujete za realitu. Vzor, který společně tkáte, dává smysl a je zábavný, přesto však zřejmě není až tak emocionálně uspokojivý. Ale vám oběma to pravděpodobně vyhovuje.",
  aquariusvscancer:
    "REFORMÁTOR A MATRIARCHA - Zpravidla jsou vaše hodnoty a cíle příliš odlišné na to, aby šly spojit. Rak chce udržet status quo; Vodnář ho chce změnit. Rak pochází z břicha, Vodnář z hlavy. Skutečnost, že mezi vámi vůbec nějaká interakce probíhá, nasvědčuje tomu, že se potřebujete jeden od druhého učit - jinak je to katastrofa!",
  aquariusvsleo:
    "REFORMÁTOR A VLADAŘ - Pro tento protiklad je nejtěžší se (opětovně) spojit, ale je to také nejdůležitější. A to proto, že představuje propast mezi privilegovanými a prostými, která způsobuje většinu nemocí a špatností světa. Až srdce Lva bude ušlechtilé a velkorysé a mysl Vodnáře poctivá a pravdivá - tehdy, a jenom tehdy, zavládne skutečný mír.",
  aquariusvsvirgo:
    "REFORMÁTOR A RÁDCE - Oba dva jste vysoce individualističtí, což může být vaše zhouba nebo dobrodiní. Zhouba - jestliže si myslíte, že byste měli být stejný typ jedince, což je logický protimluv, který způsobí soustavné zhoršování situace. Dobrodiní - pokud poskytnete jeden druhému prostor a čas potřebný k tomu, abyste nalezli sami sebe a byli více dvěma jedinečnými lidskými bytostmi než dvojicí.",
  aquariusvslibra:
    "REFORMÁTOR A DIPLOMAT - Kdybyste se trochu rozhýbali, mohli byste dosáhnout velkých věcí, a dokonce vykonat pro společnost nějakou pionýrskou práci. Mohli byste se stát pro druhé příkladem toho, jak mohou dva lidé žít v harmonii jako pár a přitom zůstat plnohodnotnými jedinci - nejdřív byste museli sestoupit ze svých hlav do svých těl - přejít od teorie k praxi.",
  aquariusvsscorpio:
    "REFORMÁTOR A ŠPIÓN - Postupujete tak rozdílně, že snadno jeden druhého zmatete. Štír chce intriky a citové uspokojení; Vodnář má sklon spíše odhalovat 'pravdu' a tíhnout k věcem, které dávají smysl. Pokud navzájem neuznáte oprávněnost svých požadavků, budete oba podráždění.",
  aquariusvsagittarius:
    "REFORMÁTOR A KNĚZ - Oba máte rádi svobodu a zkoumat život a sami sebe, a protože velmi pravděpodobně v tom jeden druhému nebudete bránit, může tato interakce dobře fungovat - doufejme ale, že se vyhnete slepému fanatismu. V průběhu času vás však svoboda dělat si, co chcete, může od sebe vzdálit, a váš vztah může být pouze předstíraný. Do té doby však určitě stihnete udělat to nejdůležitější.",
  aquariusvscapricorn:
    "REFORMÁTOR A PREZIDENT - Na první pohled to není dobré spojení - plány a sklony Kozoroha mohou být zmařeny liberálností Vodnáře, který se na oplátku cítí postižen konzervatismem Kozoroha. Ale již pouhý fakt, že mezi vámi probíhá vůbec nějaká interakce, svědčí o pravděpodobnosti toho, že se Kozoroh potřebuje zmodernizovat a uvolnit, a Vodnář dostat do reality a dát se dohromady.",
  aquariusvsaquarius:
    "DVA REFORMÁTOŘI - Společně fungujete tak dobře proto, protože oba dva žijete ve svých myslích, kde vás tak podivné věci, jako je tělo a city, tolik neruší. Diskutujete a posuzujete otázky života, a jen příležitostně sklouznete k věcem tělesným a emocionálním. Ale to nestačí, pokud už neexistuje nic, co by vás drželo pohromadě.",
  aquariusvspisces:
    "REFORMÁTOR A SPASITEL - Můžete začít s podobnými idealistickými záměry, ale právě vaše neurčitost a povrchnost vás později zaskočí, takže už si ani nebudete jistí, čím anebo kým vlastně jste jeden pro druhého. Možná si jeden z vás anebo oba myslíte, že by se měl ten druhý změnit. Možná jste se vy svým způsobem změnili. Ale nikdy není příliš pozdě... Možná.",

  piscesvsaries:
    "Nevhodný: Beran chce zvítězit, Ryby jsou připravené nastavit druhou tvář. Beran se pouští přímo do akce, Rybám je bližší pasivní odpor. Zpočátku se může zdát, že jeden t vás zachraňuje toho druhého, ale později přestane být jasné, kdo je vlastně zachráncem a kdo obětí. Je to případ tragického omylu v totožnosti - pokud ovšem oba nezničíte své osobní mýty.",
  piscesvstaurus:
    "Symbiotický: Spojuje se zde radost ze života a jistota úrodného ostrova v tajemném moři. Vzájemně si dáváte to, co ten druhý potřebuje. Ryby dostanou něco pevného, co je bude živit a držet na uzdě; Býk si zase bude vědom zázraků života. Pouze egoistické sklony jednoho - držet se v bezpečí - anebo druhého - být příliš roztěkaný - by mohly ukončit toto potenciálně úspěšné spojení.",
  piscesvsgemini:
    "Přizpůsobivý: Na esoterické úrovni jste oba spřízněni, naladěni na pravdu, kterou se dotýkáme absolutna, skrze směs humoru a pokory. Pokud však nejste duchovně ukáznění, můžete zabřednout do nicotností, protože vám bude unikat podstata. Oba někdy potřebujete, aby vás něco drželo při zemi - možná blízcí přátelé nebo dítě.",
  piscesvscancer:
    "Citlivý: Toto je taková kombinace, jakých svět potřebuje co nejvíc! Hlavní oporou je zde vaše schopnost sladit se vzájemně se svými pocity, sny a obavami a respektovat je. Navíc tuto sympatii a soucit úspěšně vyzařujete na svou rodinu, přátele a svět obecně. Dejte si ale pozor, abyste jeden druhému dovolili respektovat i své vlastní sny.",
  piscesvsleo:
    "Ohleduplný: Ryba, která nastavuje druhou tvář, může budit dojem, že dává lvu volnou ruku, aby vládl podle libosti. Ale po určité době se ukáže, že Ryby sledují svůj vlastní cíl, který Lva zákeřně ohrožuje. Lev udělá nejlépe, když bude Ryby chápat jako příklad moci bezmocných, a Ryby by zase měly považovat Lva za vzorový příklad toho, že každý si nakonec sní to, co si nadrobil.",
  piscesvsvirgo:
    "Prostý: Vy dva můžete jeden druhému skutečně pomoci zakusit citlivost spojenou s řádem. Musíte se ale vyhnout pasti, která spočívá v tom, že Pannino zaměření na detail postrádá cit pro věc, a že Ryby na to reagují přehnaně. Máte stejnou představu o tom, jak dobrý by měl život být - jen si uvědomte, že ji oba vnímáte a přistupujete k ní z protichůdných hledisek.",
  piscesvslibra:
    "Vlídný: Nerozhodnost Vah a vyhýbavost Ryb mohou budit zdání kompatibility, zdání, že se k sobě dobře hodíte, protože ani jeden z vás nechce čelit temným či obtížným věcem. Ale pokud se skutečně rozhodnete vést poctivý vztah, dělejte tak s upřímností a citlivostí - jinak se může stát pouhým přeludem.",
  piscesvsscorpio:
    "Intuitivní: Váš svazek je silný, ale zvláštní. Váš vztah obsahuje hluboké a tajemné prvky, které se odhalí pouze tehdy, až se čas naplní - a možná ani tehdy ne docela. Protože jste oba intuitivní a citoví, jste naladěni na tento skrytý proces a jste věrní tomu i jeden druhému - tedy s výjimkou občasných úskalí.",
  piscesvsagittarius:
    "Ošidný: Hlavní oporou existence je pro vás oba vize a víra, a proto vás vaše přesvědčení, dalekosáhlé představy a dobráckost mohou svést dohromady na kus cesty, který projdete téměř v extázi. Ale pokud vás něco nepřinutí ke skutečně poctivému zúčtování, pak můžete zjistit, že svou neurčitostí, shovívavostí a nepraktičností vlastně jeden druhého ničíte.",
  piscesvscapricorn:
    "Slibný: Když Kozoroh uzná, jak moc ji potřebuje a jak je pro něj užitečná rybí imaginace a emocionální citlivost, a když Ryby připustí hodnotu přízemní praktičnosti Kozoroha, pak to může připomínat šťastné setkání Nebe se Zemí. Takže nepřipusťte ani rybí vágnost, ani kozoroží zaslepenost.",
  piscesvsaquarius:
    "Nadějný: Můžete začít s podobnými idealistickými záměry, ale právě vaše neurčitost a povrchnost vás později zaskočí, takže už si ani nebudete jistí, čím anebo kým vlastně jste jeden pro druhého. Možná si jeden z vás anebo oba myslíte, že by se měl ten druhý změnit. Možná jste se vy svým způsobem změnili. Ale nikdy není příliš pozdě... Možná.",
  piscesvspisces:
    "Blouznivý: Naneštěstí jste spíše jako dva mučedníci. A 'věc', které jste padli za oběť, může být alkohol, drogy, váš 'sen' anebo někdo jiný, kdo je dokonce ještě více obětí, než za jaké se vy dva považujete. A opět, pouze tehdy vám to může vyjít, pokud se zbavíte sebelítosti nebo závislosti a skutečně se pustíte do realizace té vize, které jste dříve věřili.",
};
